package com.tripmateai.service.impl; import com.tripmateai.dto.request.user.UpdateProfileRequest; import com.tripmateai.dto.response.user.UserProfileResponse; import com.tripmateai.mapper.UserMapper; import com.tripmateai.repository.UserRepository; import com.tripmateai.security.UserPrincipal; import com.tripmateai.service.UserService; import lombok.RequiredArgsConstructor; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; @Service @RequiredArgsConstructor public class UserServiceImpl implements UserService {private final UserRepository users; private UserPrincipal current(){return (UserPrincipal)SecurityContextHolder.getContext().getAuthentication().getPrincipal();} public UserProfileResponse getCurrentUser(){return UserMapper.toProfile(current().user());} public UserProfileResponse updateProfile(UpdateProfileRequest r){var u=current().user();u.setFullName(r.fullName());u.setPhoneNumber(r.phoneNumber());u.setProfileImage(r.profileImage());return UserMapper.toProfile(users.save(u));}}
